int[] a = { 5, 1, 4 };
Array.Sort(a);
Console.WriteLine(string.Join(" ", a));
Array.Sort(a, (x, y) => y.CompareTo(x));
Console.WriteLine(string.Join(" ", a));

string[] w = { "pear", "fig", "apple", "kiwi" };
Array.Sort(w, (x, y) => {
    if (x.Length != y.Length) return x.Length.CompareTo(y.Length);
    return string.CompareOrdinal(x, y);
});
Console.WriteLine(string.Join(" ", w));

string[] w = { "pear", "fig", "apple", "kiwi" };
var sorted = w.OrderBy(s => s.Length).ThenBy(s => s, StringComparer.Ordinal).ToArray();
Console.WriteLine(string.Join(" ", sorted));
var desc = w.OrderByDescending(s => s.Length).ToArray();
Console.WriteLine(desc[0]);
